def set_what_the_hub_handles(apps, schema_editor):
    """The templates synced before had only a header text (a TEXT header); say which ones the Hub handles."""
    Template = apps.get_model("whatsapp_inbox", "Template")
    rows = Template.objects.using(schema_editor.connection.alias)
    rows.exclude(header="").update(header_format="TEXT")
    for row in rows.all():
        handled = hub_handles(row.category, row.header_format, row.header, row.buttons)
        if handled != row.supported:
            rows.filter(pk=row.pk).update(supported=handled)


